<script lang="ts">
	import { apiFetch } from '$lib/api/client'; import type { CatalogSetSummary } from '$lib/api/types';
	let { onClose, onAdded }: { onClose: () => void; onAdded: () => void } = $props(); let query = $state(''); let results = $state<CatalogSetSummary[]>([]); let selected = $state<CatalogSetSummary | null>(null); let timer: ReturnType<typeof setTimeout>;
	function search() { clearTimeout(timer); timer = setTimeout(async () => { results = query.trim() ? await apiFetch<CatalogSetSummary[]>(`/api/catalog/sets?q=${encodeURIComponent(query)}&limit=10`) : []; }, 250); }
	async function add() { if (!selected) return; await apiFetch('/api/collection', { method: 'POST', body: { set_num: selected.set_num, quantity: 1, completeness: 'complete', unknown_missing_count: 0 } }); onAdded(); onClose(); }
</script>
<div class="backdrop" role="presentation"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="add-title"><header><h2 id="add-title">Add set</h2><button aria-label="Close" onclick={onClose}>×</button></header><label>Set number or name <input bind:value={query} oninput={search} /></label>{#if !selected}<div role="listbox">{#each results as item}<button role="option" aria-selected="false" onclick={() => selected = item}>{item.set_num} {item.name}</button>{/each}</div>{:else}<p><strong>{selected.set_num} {selected.name}</strong></p><button onclick={add}>Add to collection</button>{/if}<p class="help">Can’t find it? Import it manually or from a ZIP in Settings.</p></div></div>
<style>.backdrop{position:fixed;inset:0;z-index:5;display:grid;place-items:center;padding:16px;background:#17171766}.dialog{width:min(480px,100%);padding:20px;background:var(--surface);border:1px solid var(--ink);box-shadow:6px 6px 0 #171717}.dialog header{display:flex;justify-content:space-between;align-items:center}.dialog h2{margin:0 0 16px}.dialog label{display:grid;gap:6px;font-weight:700}.dialog input{padding:9px;border:1px solid var(--ink);background:white}.dialog [role=listbox]{display:grid;margin:8px 0}.dialog [role=option]{text-align:left;padding:9px;border:1px solid var(--line);background:var(--surface)}button{font:inherit;border:1px solid var(--ink);padding:7px 10px;background:var(--yellow);font-weight:700}.help{color:var(--ink-muted);font-size:.82rem}</style>
